      },
      {
        "event_id": "lite_evt_00089",
        "explanation": "The early active-transfer answer focused on post-arrival questions rather than confirming oxygen/monitor/escort during transport.",
        "quote": "请您到呼吸科后，重点问医生以下几句话"
      }
    ],
